package ru.threediwell.fm.farm;

import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FarmContractTest {
    private JSONObject auth(String role) throws Exception{return new JSONObject().put("enabled",true).put("authenticated",true).put("user",new JSONObject().put("role",role));}
    private JSONArray module(String state,boolean disabled) throws Exception{return new JSONArray().put(new JSONObject().put("id","inventory").put("state",state).put("disabled",disabled));}
    @Test public void noModulesDoesNotDisableCorePrinting() throws Exception {Capabilities c=new Capabilities(auth("operator"),new JSONArray());assertTrue(c.operate);assertFalse(c.inventory);}
    @Test public void onlyLoadedEnabledModuleExposesInventory() throws Exception {
        for(String state:new String[]{"disabled","failed","pending_restart","license_required","version_mismatch",""})assertFalse(new Capabilities(auth("admin"),module(state,false)).inventory);
        assertFalse(new Capabilities(auth("admin"),module("loaded",true)).inventory);assertTrue(new Capabilities(auth("admin"),module("loaded",false)).inventory);
    }
    @Test public void viewingRolesCannotPrintEvenWithInventory() throws Exception {for(String role:new String[]{"observer","assembler","unknown",""}){Capabilities c=new Capabilities(auth(role),module("loaded",false));assertTrue(c.inventory);assertFalse(c.operate);}}
    @Test public void revokedAuthenticationDisablesModuleAndPrinting() throws Exception {JSONObject auth=auth("admin");auth.put("authenticated",false);Capabilities c=new Capabilities(auth,module("loaded",false));assertFalse(c.operate);assertFalse(c.inventory);}
    @Test public void changedServerDoesNotKeepPreviousInventory() throws Exception {Capabilities one=new Capabilities(auth("operator"),module("loaded",false)),two=new Capabilities(auth("operator"),new JSONArray());assertTrue(one.inventory);assertFalse(two.inventory);}
    @Test public void otherModuleAvailabilityIsRefreshedIndependently() throws Exception {JSONArray rows=module("loaded",false);rows.put(new JSONObject().put("id","diagnostics").put("state","loaded").put("disabled",false));Capabilities before=new Capabilities(auth("admin"),rows);assertTrue(before.moduleAvailable("diagnostics"));rows.getJSONObject(1).put("disabled",true);Capabilities after=new Capabilities(auth("admin"),rows);assertTrue(after.inventory);assertFalse(after.moduleAvailable("diagnostics"));assertFalse(before.sameAvailability(after));assertFalse(after.moduleAvailable("unknown"));}
    @Test public void numericPrintableAndMissingFlagsAreUnderstood() throws Exception {JSONObject f=new JSONObject().put("is_printable",1).put("compatible_pids",new JSONArray().put("p1"));assertTrue(PrintRequest.compatible(f,"p1"));assertFalse(PrintRequest.compatible(f,"p2"));f.put("missing",1);assertFalse(PrintRequest.compatible(f,"p1"));}
    @Test public void absentCompatibilityDoesNotInventSupport() throws Exception {assertFalse(PrintRequest.compatible(new JSONObject().put("is_printable",true),"p1"));}
    @Test public void printUsesServerFileAndFiltersUnsafeOptions() throws Exception {PrintRequest r=new PrintRequest("project_1","file_2","plate.3mf","p1",-1,new JSONObject().put("timelapse",true).put("force",true).put("skip_filament",true).put("raw_gcode","M112"));assertEquals("/api/projects2/project_1/files/file_2/print",r.path());JSONObject body=r.body();assertFalse(body.has("gcode_file"));assertFalse(body.has("force"));assertFalse(body.has("skip_filament"));assertEquals(1,body.getJSONObject("print_opts").length());assertEquals(-1,body.getInt("ams_slot"));}
    @Test public void quickTaskPreservesFilenameWithoutServerPath() throws Exception {PrintRequest r=new PrintRequest("","","plate.gcode.3mf","p1",null,null);assertEquals("/api/part/print",r.path());assertEquals("plate.gcode.3mf",r.body().getString("gcode_file"));assertEquals("quick",r.body().getString("source"));assertFalse(r.body().has("src_path"));}
    @Test public void identifiersCannotInjectPathOrQuery() {assertEquals("a%2Fb%3Fc%23d",FarmRepository.segment("a/b?c#d"));}
    @Test public void httpOkIsNotProofOfStart() throws Exception {for(JSONObject r:new JSONObject[]{new JSONObject(),new JSONObject().put("status","ok"),new JSONObject().put("status","low_filament"),new JSONObject().put("accepted",true).put("status","error").put("job_id","x")})assertFalse(PrintRequest.accepted(r));assertTrue(PrintRequest.accepted(new JSONObject().put("status","ok").put("accepted",true).put("job_id","j1")));}
    @Test public void noFreshnessOrMaskedIdleNeverPermitsPrint() throws Exception {JSONObject p=new JSONObject().put("type","bambu"),s=new JSONObject().put("status","IDLE").put("status_raw","RUNNING").put("seen_ago",0);assertFalse(PrinterState.ready(p,s,1));s.put("status_raw","IDLE");assertTrue(PrinterState.ready(p,s,1));assertFalse(PrinterState.ready(p,s,6500));s.remove("seen_ago");assertFalse(PrinterState.ready(p,s,1));}
    @Test public void unknownRawAndCompletedPrintAreNotIdle() throws Exception {JSONObject p=new JSONObject().put("type","klipper"),s=new JSONObject().put("status","IDLE").put("status_raw","complete").put("seen_ago",0);assertFalse(PrinterState.ready(p,s,1));s.put("status_raw","standby");assertTrue(PrinterState.ready(p,s,1));s.put("seen_ago",60);assertFalse(PrinterState.ready(p,s,1));}
    @Test public void oldOrCompletedFileDoesNotShowCurrentProgress() throws Exception {JSONObject s=new JSONObject().put("status","RUNNING").put("percent",80).put("seen_ago",0);assertEquals(80,PrinterState.progress(s,1));assertEquals(-1,PrinterState.progress(s,6500));for(String status:new String[]{"IDLE","FINISH","ERROR","OFFLINE","UNKNOWN"}){s.put("status",status);assertEquals(-1,PrinterState.progress(s,1));}}
    @Test public void unknownProgressIsHiddenInsteadOfInventingZero() throws Exception {JSONObject s=new JSONObject().put("status","RUNNING").put("seen_ago",0);assertEquals(-1,PrinterState.progress(s,1));s.put("percent",JSONObject.NULL);assertEquals(-1,PrinterState.progress(s,1));s.put("percent","unknown");assertEquals(-1,PrinterState.progress(s,1));s.put("percent",0);assertEquals(0,PrinterState.progress(s,1));}
    @Test public void pausedPrintingKeepsProgressAndClampsServerValues() throws Exception {JSONObject s=new JSONObject().put("status","PAUSED").put("seen_ago",0).put("percent",145);assertEquals(100,PrinterState.progress(s,1));s.put("percent",-10);assertEquals(0,PrinterState.progress(s,1));s.put("seen_ago",90);assertEquals(-1,PrinterState.progress(s,1));}
    private static class Memory implements PrintJournal.Store{String value="";boolean writable=true;public String read(){return value;}public boolean write(String v){if(!writable)return false;value=v;return true;}public boolean clear(){if(!writable)return false;value="";return true;}}
    private PrintRequest request(){return new PrintRequest("","","plate.gcode","p1",null,null);}
    @Test public void uncertainStartBlocksTheSamePrinterAcrossRecreation() throws Exception {Memory m=new Memory();new PrintJournal(m).begin("http://farm",request(),1);PrintJournal restored=new PrintJournal(m);assertTrue(restored.blocks("http://farm","p1"));assertEquals("",restored.find("http://farm","p1").jobId());try{restored.begin("http://farm",request(),2);fail();}catch(IllegalStateException expected){}assertFalse(restored.blocks("http://another-farm","p1"));}
    @Test public void acceptedSendPersistsJobIdWithoutCredentials() throws Exception {Memory m=new Memory();PrintJournal j=new PrintJournal(m);j.begin("http://farm",request(),1);j.accepted("http://farm","p1","job1",2);assertEquals("job1",new PrintJournal(m).find("http://farm","p1").jobId());assertFalse(m.value.contains("cookie"));assertFalse(m.value.contains("password"));}
    @Test public void failedPersistencePreventsStart() throws Exception {Memory m=new Memory();m.writable=false;try{new PrintJournal(m).begin("http://farm",request(),1);fail();}catch(IllegalStateException expected){}assertEquals("",m.value);}
    @Test public void malformedJournalFailsClosed() throws Exception {Memory m=new Memory();m.value="broken";PrintJournal j=new PrintJournal(m);assertTrue(j.pending("http://farm"));assertTrue(j.blocks("http://farm","p1"));assertTrue(j.blocks("http://another-farm","p2"));try{j.begin("http://farm",request(),1);fail();}catch(IllegalStateException expected){}j.clear("","");assertFalse(j.blocks("http://farm","p1"));}
    @Test public void explicitClearOnlyClearsLocalMarker() throws Exception {Memory m=new Memory();PrintJournal j=new PrintJournal(m);j.begin("http://farm",request(),1);j.clear("http://farm","p1");assertFalse(j.pending("http://farm"));assertEquals("",m.value);}
}
